package io.github.jichuo1.dexmeguviz.precompute;

import java.util.*;
import static io.github.jichuo1.dexmeguviz.precompute.OfflineJson.*;

/** Mirrors the supported local certificates, not the complete query decision. */
final class LocalCertificates {
    final SourceCatalog catalog;final Budget budget;final Map<String,Map<String,Object>> old=new LinkedHashMap<>(),checked=new LinkedHashMap<>();int visitedNodes;
    LocalCertificates(SourceCatalog catalog,Budget budget){this.catalog=catalog;this.budget=budget;for(LocalDex d:catalog.decoded.values())d.work=0;}
    private static final class Context {final int source;final long ordinal;Context(int source,long ordinal){this.source=source;this.ordinal=ordinal;}}
    private int source(Object value){long n=num(value);need(n>=0&&n<catalog.sources.size(),"EvidenceMismatch","evidence source");return (int)n;}
    Map<String,Map<String,Object>> verify(Map<String,Object> result,List<Object> certificates){
        need(certificates.size()<=100000,"BudgetExceeded","certificate count");for(Object item:certificates){Map<String,Object> c=obj(item);String pointer=str(c.get("pointer"));need(old.put(pointer,c)==null,"EvidenceMismatch","duplicate certificate pointer");}
        List<Object> candidates=arr(result.get("candidates"));visit(candidates,"/candidates",null,0);visit(result.containsKey("frontiers")?result.get("frontiers"):new ArrayList<Object>(),"/frontiers",null,0);
        for(int i=0;i<candidates.size();i++)need(checked.containsKey("/candidates/"+i),"Unsupported","candidate identity not covered");need(checked.keySet().equals(old.keySet()),"EvidenceMismatch","certificate coverage differs");return checked;
    }
    private void visit(Object value,String pointer,Context inherited,int depth){
        budget.charge(1);need(depth<=48&&++visitedNodes<=200000&&checked.size()<=100000,"BudgetExceeded","local evidence tree");
        if(value instanceof List){List<Object> a=arr(value);for(int i=0;i<a.size();i++)visit(a.get(i),pointer+'/'+i,inherited,depth+1);return;}if(!(value instanceof Map))return;
        Map<String,Object> data=obj(value);String relation=data.get("relation") instanceof String?(String)data.get("relation"):null;Integer src=null;if(data.containsKey("source_index"))src=Integer.valueOf(source(data.get("source_index")));else if(inherited!=null)src=Integer.valueOf(inherited.source);Context context=inherited;LocalDex dex=src==null?null:catalog.dex(src);Map<String,Object> certificate=null;Long ordinal=null;
        if(data.containsKey("snapshot_id"))equal(data.get("snapshot_id"),catalog.snapshotId,"SourceMismatch","snapshot identity");
        if(src!=null){PrecomputedCandidates.Source source=catalog.sources.get(src);for(String field:Arrays.asList("content_id","logical_dex_id","occurrence_id"))if(data.containsKey(field))equal(data.get(field),field.equals("content_id")?source.contentId:field.equals("logical_dex_id")?source.logicalDexId:source.occurrenceId,"SourceMismatch","source identity frame");}
        if(src!=null&&data.containsKey("source_sha256"))equal(data.get("source_sha256"),catalog.sources.get(src).dexSha256,"SourceMismatch","candidate source digest");
        if(src!=null&&data.containsKey("input_index"))equal(data.get("input_index"),n(catalog.sources.get(src).inputIndex),"SourceMismatch","candidate input occurrence");
        if(data.containsKey("method_index")&&data.containsKey("declaration_offset")&&relation==null){relation="method_defs";need(old.containsKey(pointer),"EvidenceMismatch","missing legacy method locator");ordinal=num(obj(old.get(pointer).get("value")).get("local_index"));}
        else if(Arrays.asList("method_defs","class_defs","field_defs","method_refs","field_refs","type_refs","string_values").contains(relation)&&data.containsKey("local_index"))ordinal=num(data.get("local_index"));
        if(ordinal!=null){need(dex!=null&&ordinal>=0,"EvidenceMismatch","entity source/ordinal");Map<String,Object> actual=dex.describe(relation,ordinal);
            for(Map.Entry<String,Object> field:data.entrySet()){String key=field.getKey();if(key.equals("method_index"))key="reference_index";else if(key.equals("definition_offset"))key="declaration_offset";else if(key.equals("descriptor"))key="type_descriptor";if(actual.containsKey(key)&&field.getValue()!=null&&!field.getKey().equals("relation"))equal(field.getValue(),actual.get(key),"EvidenceMismatch","candidate field differs: "+key);}
            certificate=map("pointer",pointer,"source_index",n(src),"value",actual);if(relation.equals("method_defs"))context=new Context(src,ordinal);
        }else if(Arrays.asList("string_uses","invoke_sites","field_uses","type_uses").contains(relation)&&data.containsKey("dex_pc")){
            need(dex!=null,"EvidenceMismatch","use source");long caller=num(data.containsKey("caller_ordinal")?data.get("caller_ordinal"):data.get("local_index")),pc=num(data.get("dex_pc"));need(caller>=0&&pc>=0,"EvidenceMismatch","use identity");if(data.containsKey("local_index"))equal(data.get("local_index"),n(caller),"EvidenceMismatch","caller ordinal disagreement");Map<String,Object> method=dex.describe("method_defs",caller),event=dex.event(caller,pc);String domain=relation.equals("string_uses")?"string_value":relation.equals("invoke_sites")?"method_ref":relation.equals("field_uses")?"field_ref":"type_ref";equal(event.get("target_domain"),domain,"EvidenceMismatch","use relation/opcode family");
            if(data.containsKey("caller_method_ref"))equal(data.get("caller_method_ref"),method.get("reference_index"),"EvidenceMismatch","caller method ref");for(String key:Arrays.asList("owner","name","prototype"))if(data.containsKey(key)&&data.get(key)!=null)equal(data.get(key),method.get(key),"EvidenceMismatch","use caller symbol");if(data.containsKey("extra_proto"))need(data.get("extra_proto")==null,"EvidenceMismatch","ordinary use extra prototype");if(data.containsKey("instruction_offset"))equal(data.get("instruction_offset"),n(num(event.get("code_offset"))+16+pc*2),"EvidenceMismatch","instruction byte offset");if(data.containsKey("target_descriptor")){equal(domain,"type_ref","EvidenceMismatch","type target domain");equal(data.get("target_descriptor"),obj(event.get("target")).get("type_descriptor"),"EvidenceMismatch","type target descriptor");}for(String key:Arrays.asList("opcode","target_index","target_domain","code_offset"))if(data.containsKey(key))equal(data.get(key),event.get(key),"EvidenceMismatch","use field differs");certificate=map("pointer",pointer,"source_index",n(src),"event",event);context=new Context(src,caller);
        }else if(data.keySet().containsAll(Arrays.asList("caller","resolved","dex_pc","target_method_ref"))){
            Map<String,Object> caller=obj(data.get("caller")),resolved=obj(data.get("resolved"));equal(caller.get("relation"),"method_defs","EvidenceMismatch","hop caller domain");equal(resolved.get("relation"),"method_defs","EvidenceMismatch","hop resolved domain");need(caller.get("dex_pc")==null&&resolved.get("dex_pc")==null,"EvidenceMismatch","hop entity PC");src=source(caller.get("source_index"));long method=num(caller.get("local_index")),pc=num(data.get("dex_pc"));dex=catalog.dex(src);Map<String,Object> event=dex.event(method,pc);equal(event.get("target_domain"),"method_ref","EvidenceMismatch","hop reference domain");equal(event.get("target_index"),data.get("target_method_ref"),"EvidenceMismatch","hop reference");equal(event.get("opcode"),data.get("opcode"),"EvidenceMismatch","hop opcode");Map<String,Object> target=catalog.dex(source(resolved.get("source_index"))).describe("method_defs",num(resolved.get("local_index")));for(String key:Arrays.asList("owner","name","prototype"))equal(target.get(key),obj(event.get("target")).get(key),"EvidenceMismatch","resolved hop symbol");certificate=map("pointer",pointer,"source_index",n(src),"event",event);
        }else if(data.containsKey("kind")&&data.containsKey("node_id")){
            String kind=str(data.get("kind"));need(Arrays.asList("metadata","string_use","invoke","field_use","type_use","instruction_scope","no_body").contains(kind),"Unsupported","local witness kind");
            if(!kind.equals("metadata")){Context witness=context;if(data.get("entity") instanceof Map){Map<String,Object> entity=obj(data.get("entity"));if("method_defs".equals(entity.get("relation")))witness=new Context(source(entity.get("source_index")),num(entity.get("local_index")));}need(witness!=null,"Unsupported","witness method context");src=witness.source;long method=witness.ordinal;dex=catalog.dex(src);Map<String,Object> bytes;
                if(kind.equals("no_body")){equal(dex.describe("method_defs",method).get("code_offset"),n(0),"EvidenceMismatch","no-body witness");bytes=dex.codeCertificate(method);}
                else if(kind.equals("instruction_scope")){bytes=dex.codeCertificate(method);equal(data.get("code_units"),bytes.get("code_units"),"EvidenceMismatch","instruction scope size");}
                else{bytes=dex.event(method,num(data.get("dex_pc")));equal(data.get("opcode"),bytes.get("opcode"),"EvidenceMismatch","witness opcode");equal(data.get("reference_index"),bytes.get("target_index"),"EvidenceMismatch","witness target index");String domain=kind.equals("string_use")?"string_value":kind.equals("invoke")?"method_ref":kind.equals("field_use")?"field_ref":"type_ref";equal(bytes.get("target_domain"),domain,"EvidenceMismatch","witness domain");if(data.containsKey("target_descriptor"))equal(data.get("target_descriptor"),obj(bytes.get("target")).get("type_descriptor"),"EvidenceMismatch","witness descriptor");}
                certificate=map("pointer",pointer,"source_index",n(src),"local_bytes",bytes);
            }
        }
        if(certificate!=null){need(checked.put(pointer,certificate)==null,"EvidenceMismatch","duplicate observed certificate");equal(old.get(pointer),certificate,"EvidenceMismatch","local certificate differs");}
        for(Map.Entry<String,Object> field:data.entrySet()){String key=field.getKey();if(key.equals("source_index")||key.equals("relation"))continue;Context child=context;if(key.equals("seed_witnesses")&&data.get("seed") instanceof Map){Map<String,Object> seed=obj(data.get("seed"));equal(seed.get("relation"),"method_defs","EvidenceMismatch","seed witness domain");child=new Context(source(seed.get("source_index")),num(seed.get("local_index")));}visit(field.getValue(),pointer+'/'+key,child,depth+1);}
    }
}
